/**
 * Plain text still arriving, with a steady caret (`design/components/streaming-text.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/streaming-text.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { Component, ViewEncapsulation, input } from '@angular/core'

import { MEMBER_PROVIDERS, SlotOutlet, SlotTemplate, useMember } from '@polymorph/angular'
import styles from '@polymorph/recipes/ai/streaming-text.module.css'
import { Skeleton, type SkeletonProps } from '../structure/Skeleton'

export type StreamingTextSize = NonNullable<StreamingTextProps['size']>

/** Plain text still arriving, with a steady caret: the inputs it takes, by the React member's prop names. */
export interface StreamingTextProps {
  /**
   * The text step (Text's `sm` or `md`), for the same reason Text has two.
   */
  size?: 'sm' | 'md'
  /**
   * Whether more is coming, which shows the caret and sets `aria-busy` on the root.
   */
  streaming?: boolean
}

/** Plain text still arriving, with a steady caret. */
@Component({
  selector: 'pm-streaming-text',
  encapsulation: ViewEncapsulation.None,
  host: { style: 'display: contents' },
  providers: [...MEMBER_PROVIDERS],
  imports: [SlotOutlet, SlotTemplate, Skeleton],
  // prettier-ignore
  template: `<ng-template pmSlot="default" [pmSlotOf]="$"><ng-content /></ng-template>
<div
[attr.class]="e1()"
[attr.data-size]="e2()"
[attr.data-state]="e3()"
[attr.data-pending]="e4()"
[attr.aria-busy]="e5()"
data-member="streaming-text"
>@if (e6()) {<pm-skeleton
shape="text"
[textStep]="e7()"
[width]="e8()"
></pm-skeleton>} @else {<p
[attr.class]="e9()"
><ng-container [pmSlotOutlet]="'default'" [pmSlotOf]="$" />
@if (e10()) {<span
[attr.class]="e11()"
aria-hidden="true"
></span>}</p>}</div>`,
})
export class StreamingText {
  /**
   * The text step (Text's `sm` or `md`), for the same reason Text has two.
   */
  readonly size = input<Exclude<StreamingTextProps['size'], undefined>, StreamingTextProps['size']>(
    'md',
    { transform: (value: StreamingTextProps['size']) => (value === undefined ? 'md' : value) },
  )
  /**
   * Whether more is coming, which shows the caret and sets `aria-busy` on the root.
   */
  readonly streaming = input<
    Exclude<StreamingTextProps['streaming'], undefined>,
    StreamingTextProps['streaming']
  >(false, {
    transform: (value: StreamingTextProps['streaming']) => (value === undefined ? false : value),
  })
  protected readonly $ = useMember({
    events: [],
    props: { size: () => this.size(), streaming: () => this.streaming() },
  })
  protected readonly $p = this.$.props

  protected e1() {
    return styles.root
  }

  protected e2() {
    return this.$p.size
  }

  protected e3() {
    return this.$p.streaming ? 'streaming' : undefined
  }

  protected e4() {
    return this.$p.streaming && this.$.text('default') === '' ? '' : undefined
  }

  protected e5() {
    return this.$p.streaming ? true : undefined
  }

  protected e6() {
    return this.$p.streaming && this.$.text('default') === ''
  }

  protected e7(): SkeletonProps['textStep'] {
    if (!(this.$p.streaming && this.$.text('default') === '')) return undefined as never
    return this.$p.size
  }

  protected e8(): SkeletonProps['width'] {
    if (!(this.$p.streaming && this.$.text('default') === '')) return undefined as never
    return 9
  }

  protected e9() {
    if (this.$p.streaming && this.$.text('default') === '') return undefined as never
    return styles.text
  }

  protected e10() {
    if (this.$p.streaming && this.$.text('default') === '') return undefined as never
    return this.$p.streaming
  }

  protected e11() {
    if (this.$p.streaming && this.$.text('default') === '') return undefined as never
    if (!this.$p.streaming) return undefined as never
    return styles.caret
  }
}
